"""Generate dictionary constants; --check verifies committed outputs."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def generate(check=False):
    entries = json.loads((ROOT / 'shared/dict-types.json').read_text(encoding='utf-8'))
    for field in ('name', 'dict_type'):
        values = [entry[field] for entry in entries]
        if len(values) != len(set(values)):
            raise ValueError(f'Duplicate {field}')
    outputs = {
        'backend/app/modules/system/dict/constants.py': '# Generated by scripts/generate_dict_types.py\nfrom enum import StrEnum\n\n\nclass DictType(StrEnum):\n' + ''.join(f'    {e["name"]} = "{e["dict_type"]}"\n' for e in entries),
        'frontend/web/src/constants/dict-types.ts': '// Generated by scripts/generate_dict_types.py\nexport enum DictTypeEnum {\n' + ''.join(f'  {e["name"]} = "{e["dict_type"]}",\n' for e in entries) + '}\n',
    }
    for name, content in outputs.items():
        path = ROOT / name
        if check:
            if not path.exists() or path.read_text(encoding='utf-8') != content:
                raise SystemExit(f'Outdated: {name}')
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding='utf-8')

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    generate(parser.parse_args().check)
